+++ b/training/level-1/L1-002-text-normalize/normalizeText.mjs
@@ -0,0 +1,77 @@
+export function normalizeText(input, options = {}) {
+  if (input === null || input === undefined) {
+    return '';
+  }
+
+  // Default options
+  const defaultOptions = {
+    trimTrailing: true,
+    collapseHorizontalWhitespace: true,
+    collapseBlankLines: true,
+    trim: true
+  };
+
+  const { trimTrailing, collapseHorizontal, collapseBlankLines, trim } = {
+    ...defaultOptions,
+    ...options
+  };
+
+  // Normalize CRLF and CR to LF
+  let normalized = String(input).replace(/\r\n/g, '\n').replace(/\r/g, '\n');
+
+  // Split into lines
+  const lines = normalized.split('\n');
+
+  // Process each line
+  const processedLines = lines.map(line => {
+    // Trim trailing spaces/tabs if trimTrailing is true
+    if (trimTrailing) {
+      line = line.replace(/\s+$/g, '');
+    }
+
+    // Collapse runs of spaces/tabs inside each line to one space if collapseHorizontalWhitespace is true
+    if (collapseHorizontal) {
+      line = line.replace(/\s+/g, ' ');
+    }
+
+    return line;
+  });
+
+  // Collapse 3+ newlines to exactly 2 if collapseBlankLines is true
+  if (collapseBlankLines) {
+    const newProcessedLines = [];
+    let consecutiveBlanks = 0;
+
+    for (const line of processedLines) {
+      if (line === '') {
+        consecutiveBlanks++;
+      } else {
+        if (consecutiveBlanks > 0) {
+          newProcessedLines.push('\n\n');
+          consecutiveBlanks = 0;
+        }
+        newProcessedLines.push(line);
+      }
+    }
+
+    // Handle trailing blank lines
+    if (consecutiveBlanks > 0) {
+      newProcessedLines.push('\n\n');
+    }
+
+    processedLines.length = 0;
+    for (const line of newProcessedLines) {
+      processedLines.push(line);
+    }
+  }
+
+  // Join lines back together
+  normalized = processedLines.join('\n');
+
+  // Trim entire result if trim is true
+  if (trim) {
+    normalized = normalized.trim();
+  }
+
+  return normalized;
+}

